// worker.ts: the Worker entry (wrangler "main"). Copy to the project root.
// OpenNext builds .open-next/worker.js with a fetch handler only. This file adds the daily job.
// Verify the generated file after `npm run cf:build`: its default export must still be { fetch }.

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: generated by the OpenNext build, which has no type declarations
import handler from "./.open-next/worker.js";

// Re-export the Durable Object classes that OpenNext's worker exports. Without this, wrangler cannot find them.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore: on a fresh project `next build` type-checks this file before OpenNext has written .open-next/worker.js
export * from "./.open-next/worker.js";

const worker = {
  fetch: (request: Request, env: CloudflareEnv, ctx: ExecutionContext) => handler.fetch(request, env, ctx),

  // Runs the daily job inside the app, through the self binding. It reuses the route handler and the database config.
  scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(
      // The self binding is always a Fetcher at runtime; the generated type makes its fetch look optional.
      (env.WORKER_SELF_REFERENCE as Fetcher).fetch("https://worker/api/cron/daily", {
        method: "POST",
        headers: { authorization: `Bearer ${env.CRON_SECRET}` },
      }),
    );
  },
};

export default worker;
